/* 第一章完整材料题库（续）。 */
TS('t06','1.3','角边角（ASA）与角角边（AAS）',
 '两角及其夹边分别相等可用 ASA；两角分别相等且其中一组等角的对边相等可用 AAS。',
 '找等角时重点利用公共角、对顶角、直角、余角、角平分线和平行线。',
 '只有两角相等不能判定全等，必须再有一组对应边相等。',
 C1('c1-6-1','1.3 巩固训练2 第1题','证明题','如图，AB=AC，AB⊥AC，AD⊥AE，且 ∠ABD=∠ACE。证明 BD=CE。','BD=CE',['由两组垂直关系，∠BAD=∠CAE。','在 △ABD 与 △ACE 中，∠BAD=∠CAE，AB=AC，∠ABD=∠ACE。','所以 △ABD≌△ACE（ASA），对应边 BD=CE。'],[],'c1-6-1',{alsoQuestion:true}),
 C1('c1-6-2','1.3 巩固训练2 第2题','证明题','如图，AB∥CD，AF∥DE，BE=CF。证明 AB=DC。','AB=DC',['由 AB∥CD 得 ∠B=∠C；由 AF∥DE 得 ∠AFB=∠DEC。','BE=CF，所以 BF=CE。','△ABF≌△DCE（ASA），因此 AB=DC。'],[],'c1-6-2'),
 C1('c1-6-3','1.3 巩固训练2 第3题','证明题','如图，D 是 △ABC 的边 AB 上一点，∠A=∠ACF，DF 交 AC 于 E，DE=EF。证明 AE=CE。','AE=CE',['∠AED=∠CEF（对顶角）。','在 △ADE 与 △CFE 中，∠A=∠ACF，∠AED=∠CEF，DE=EF。','所以 △ADE≌△CFE（AAS），得 AE=CE。'],[],'c1-6-3'),
 C1('c1-6-4','1.3 巩固训练2 第4题','解答题','如图，在 Rt△ABC 中，BC=AC，∠ACB=90°。AD⊥EC 于 D，BE⊥EC 于 E。判断“△BEC≌△CDA”是否正确，并说明理由。','正确',['∠E=∠ADC=90°。','由直角关系可得 ∠BCE=∠CAD。','又 BC=CA，所以 △BEC≌△CDA（AAS）。'],[],'c1-6-4')
);

TS('c1-06','1.3','边角边（SAS）与条件补充',
 '两边及其夹角分别相等的两个三角形全等，简写为 SAS；“两边及其中一边的对角”即 SSA 不能作为一般全等判定。',
 'SAS 要严格确认相等角是两组相等边的夹角；常用公共角、对顶角和线段和差补条件。',
 '不要把 SSA 误当作判定条件。',
 C1('c1-7-1','1.3 巩固训练3 第1题','证明题','如图，线段 AC、BD 相交于 E，AE=DE，BE=CE。证明 △ABE≌△DCE。','△ABE≌△DCE（SAS）',['∠AEB=∠DEC（对顶角）。','AE=DE，BE=CE，两边及其夹角分别相等。','所以 △ABE≌△DCE（SAS）。'],[],'c1-7-1',{alsoQuestion:true}),
 C1('c1-7-2','1.3 巩固训练3 第2题','选择题','如图，AB 平分 ∠DAC，要用 SAS 判定 △ABC≌△ABD，还需要条件（　）。','C',['AB 是公共边，且 ∠CAB=∠DAB。','使用 SAS 还需要夹角另一边相等，即 AC=AD。'],['DB=CB','∠ABC=∠ABD','AD=AC','∠D=∠C'],'c1-7-2'),
 C1('c1-7-3','1.3 巩固训练3 第3题','选择题','如图，AE∥DF，AE=DF。要使 △EAC≌△FDB，需要添加的条件是（　）。','A',['由 AE∥DF 得 ∠A=∠D。','已知 AE=DF，若 AB=CD，则利用公共部分可得 AC=DB，于是可用 SAS。'],['AB=CD','EC=BF','∠A=∠D','AB=BC'],'c1-7-3'),
 C1('c1-7-4','1.3 巩固训练3 第4题','填空题','如图，已知 AB=AC，用 SAS 证明 △ABD≌△ACE，还需添加条件____。','AD=AE',['图中有公共角 ∠A。','已知 AB=AC，再补充夹角另一边 AD=AE，即可用 SAS。'],[],'c1-7-4'),
 C1('c1-7-5','1.3 巩固训练3 第5题','证明题','如图，A、B、C、D 在同一直线上，AC=BD，∠1=∠2，EC=FB。证明 △DBF≌△ACE。','△DBF≌△ACE（SAS）',['由 ∠1=∠2 得 ∠FBD=∠ECA。','FB=EC，BD=CA。','所以 △DBF≌△ACE（SAS）。'],[],'c1-7-5'),
 C1('c1-7-6','1.3 巩固训练3 第6题','解答题','如图，在正方形 ABCD 中，E、F 分别在 CD、AD 上，且 AF=CE。（1）证明 △ABF≌△CBE；（2）若 AB=4，AF=1，求四边形 BEDF 的面积。','（1）△ABF≌△CBE；（2）12',['正方形中 AB=CB，∠A=∠C=90°，且 AF=CE，所以 △ABF≌△CBE（SAS）。','正方形面积为 16，△ABF 与 △CBE 面积均为 1/2×4×1=2。','四边形 BEDF 面积=16−2−2=12。'],[],'c1-7-6')
);

TS('c1-07','1.3','全等性质与线段、平行综合',
 '证明三角形全等后，可继续利用对应边、对应角相等推导线段关系和平行关系。',
 '遇到中点、延长线、平行目标时，先从中点得到等边，再通过对顶角或夹角构造全等。',
 '完成全等证明后不要停在“全等”，要继续写出题目要求的对应结论。',
 C1('c1-7-7','1.3 巩固训练3 第7题','证明题','如图，D、E 分别是 △ABC 的边 AB、AC 的中点，F 在 DE 的延长线上，且 EF=DE。证明：（1）BD=FC；（2）AB∥CF。','BD=FC；AB∥CF',['AD=BD，AE=CE。','在 △ADE 与 △CFE 中，AE=CE，DE=FE，∠AED=∠CEF，所以两三角形全等（SAS）。','得 AD=CF、∠A=∠ECF；于是 BD=FC，且 AB∥CF。'],[],'c1-7-7',{alsoQuestion:true}),
 C1('c1-7-8','1.3 巩固训练3 第8题','选择题','利用全等三角形测量距离的依据是（　）。','B',['测量不可直接得到的距离，是把它转化为全等三角形的一条对应边。','依据是全等三角形对应边相等。'],['全等三角形的对应角相等','全等三角形的对应边相等','大小和形状相同的两个三角形全等','三边对应相等的两个三角形全等']),
 C1('c1-7-9','1.3 巩固训练3 第9题','证明题','如图，AB=DE，BF=EC，∠B=∠E。证明 AC∥DF。','AC∥DF',['由 BF=EC，得到 BC=EF。','在 △ABC 与 △DEF 中，AB=DE，∠B=∠E，BC=EF，所以两三角形全等（SAS）。','对应角 ∠ACB=∠DFE，因此 AC∥DF。'],[],'c1-7-9')
);

TS('c1-08','1.3','全等三角形性质与判定的综合应用',
 '综合题通常先证明一组全等，再把对应边、对应角结论用于下一步；有时需要连续构造两次全等。',
 '按“找全等对象—列条件—得对应结论—继续推理”的链条书写。',
 '题目给出的垂直、平行、中点、角平分线往往同时承担多个条件来源。',
 C1('c1-8-1','1.3 巩固训练4 第1题','证明题','如图，A、F、C、D 在同一直线上，AB⊥BC，DE⊥EF，垂足分别为 B、E，AB=DE，∠A=∠D。证明 AC=DF。','AC=DF',['∠B=∠E=90°。','结合 AB=DE、∠A=∠D，可得 △ABC≌△DEF（ASA）。','对应边 AC=DF。'],[],'c1-8-1',{alsoQuestion:true}),
 C1('c1-8-2','1.3 巩固训练4 第2题','解答题','如图，在 △ABC 中，D 是 BC 上一点，AB=DB，BE 平分 ∠ABC，交 AC 于 E，连接 DE。（1）证明 △ABE≌△DBE；（2）若 ∠A=100°，∠C=50°，求 ∠DEB。','（1）△ABE≌△DBE；（2）65°',['BE 平分 ∠ABC，所以 ∠ABE=∠DBE；AB=DB；BE 为公共边，所以两三角形全等（SAS）。','∠ABC=30°，所以 ∠ABE=15°。','在 △ABE 中 ∠AEB=65°，由全等得 ∠DEB=65°。'],[],'c1-8-2'),
 C1('c1-8-3','1.3 巩固训练4 第3题','填空题','如图，在 △ABC 中，∠ACB=90°，BC=6。过 B 作 BD⊥AB 且 BD=AB，延长 BC 至 E，使 CE=BC，连接 DE 并延长交 AC 于 F，若 DE=EF，则 AC=____。','12',['按材料解析，作 DG⊥BE。利用 AAS 可证明 △ABC≌△BDG，得到 AC=BG。','再由 DE=EF 等条件证明 △CFE≌△GDE，得到 CE=EG。','由 CE=BC 且材料解析中的等量关系，最终得到 AC=12。'],[],'c1-8-3'),
 C1('c1-8-4','1.3 巩固训练4 第4题','解答题','如图，△ABC 中 D 在 BC 上，AB=AD；E 在 △ABC 外，AC=AE，连接 DE 与 AC 交于 O，且 ∠CAE=∠BAD。（1）证明 △ABC≌△ADE；（2）若 ∠BAD=25°，求 ∠EDC。','（1）△ABC≌△ADE；（2）25°',['由 ∠CAE=∠BAD，加上公共角 ∠CAD，得 ∠DAE=∠BAC。','AB=AD，AC=AE，所以 △ABC≌△ADE（SAS）。','由对应角及对顶角关系，得到 ∠EDC=∠CAE=∠BAD=25°。'],[],'c1-8-4'),
 C1('c1-8-5','1.3 巩固训练4 第5题','证明题','如图，在四边形 ABCD 中，AD∥BC，E 为 CD 中点，连接 AE、BE，延长 AE 交 BC 延长线于 F。（1）证明 △DAE≌△CFE；（2）若 AB=BC+AD，证明 BE⊥AF。','△DAE≌△CFE；BE⊥AF',['AD∥BC，得 ∠ADE=∠FCE；E 为中点，DE=EC；又有对顶角，所以 △DAE≌△CFE（ASA）。','由全等得 AE=EF、AD=CF。条件 AB=BC+AD 推出 AB=BF。','在 △ABE 与 △FBE 中，AB=BF，AE=EF，BE 公共，所以两三角形全等（SSS）。于是 ∠AEB=∠FEB=90°，BE⊥AF。'],[],'c1-8-5')
);

// 1.4 尺规作三角形 ----------------------------------------------------------
TS('t07','1.4','尺规作三角形的三种基本类型',
 '材料给出三类基本作图：已知三边；已知两角及其夹边；已知两边及其夹角。对应依据分别是 SSS、ASA、SAS。',
 '先作一条给定边或一个给定角，再用圆规截取边长、作角，最后连接交点。',
 '已知三边作图前必须满足三边关系；无刻度直尺只能作直线、射线、线段，不能直接读长度。',
 C1('c1-9-e1','1.4 尺规作图类型1','作图题','已知三条线段 a、b、c（任意两条之和大于第三条），求作 △ABC，使三边分别为 a、b、c。','按 SSS 作图',['作 AB=c。','分别以 A、B 为圆心，以 b、a 为半径作弧，交于 C。','连接 AC、BC，所得 △ABC 即为所求。'],[],'c1-9-e1',{alsoQuestion:true}),
 C1('c1-9-e2','1.4 尺规作图类型2','作图题','已知 ∠α、∠β 和线段 c，求作 △ABC，使 ∠A=∠α，∠B=∠β，AB=c。','按 ASA 作图',['先作给定长度的边。','在边的两个端点分别作给定的两个角。','两条射线相交得到第三个顶点，连接形成三角形。'],[],'c1-9-e2'),
 C1('c1-9-e3','1.4 尺规作图类型3','作图题','已知线段 a、c 和 ∠α，求作 △ABC，使 BC=a，AB=c，∠ABC=∠α。','按 SAS 作图',['作 ∠EBF=∠α。','在两条射线上分别截取 BA=c、BC=a。','连接 AC，所得 △ABC 即为所求。'],[],'c1-9-e3')
);
